class Solution {
    fun highestRankedKItems(grid:Array<IntArray>,pricing:IntArray,start:IntArray,k:Int):List<List<Int>>{
        val rows=grid.size;
        val columns=grid[0].size;
        val seen=Array(rows){
            BooleanArray(columns)
        };
        val queue=java.util.ArrayDeque<IntArray>();
        queue.add(intArrayOf(start[0],start[1],0));
        seen[start[0]][start[1]]=true;
        val items=mutableListOf<IntArray>();
        val directions=arrayOf(intArrayOf(1,0),intArrayOf(-1,0),intArrayOf(0,1),intArrayOf(0,-1));
        while(queue.isNotEmpty()){
            val state=queue.removeFirst();
            val value=grid[state[0]][state[1]];
            if(value>1&&value in pricing[0]..pricing[1])items.add(intArrayOf(state[2],value,state[0],state[1]));
            for(direction in directions){
                val r=state[0]+direction[0];
                val c=state[1]+direction[1];
                if(r in 0 until rows&&c in 0 until columns&&!seen[r][c]&&grid[r][c]!=0){
                    seen[r][c]=true;
                    queue.add(intArrayOf(r,c,state[2]+1))
                }
            }
        };
        items.sortWith(Comparator{
            a,b->var result=0;
            for(i in 0..3)if(result==0)result=a[i].compareTo(b[i]);
            result
        });
        return items.take(k).map{
            listOf(it[2],it[3])
        }
    }
}

